import type { Request, Response } from 'express';
import { Router } from 'express';
import _ from 'lodash';

import type { Auth } from '@verdaccio/auth';
import { validationUtils } from '@verdaccio/core';
import { WebUrls, rateLimit } from '@verdaccio/middleware';
import type { Config, JWTSignOptions, RemoteUser } from '@verdaccio/types';

import { getSecurity } from '../../../lib/auth-utils';
import { API_ERROR, APP_ERROR, HEADERS, HTTP_STATUS, TOKEN_BEARER } from '../../../lib/constants';
import { ErrorCode } from '../../../lib/utils';
import type { $NextFunctionVer } from '../../../types';
import { wrapSecPath } from './utils';

function addUserAuthApi(auth: Auth, config: Config): Router {
  const route = Router();
  route.post(
    wrapSecPath(WebUrls.user_login),
    rateLimit(config?.userRateLimit),
    function (req: Request, res: Response, next: $NextFunctionVer): void {
      const username = req.body?.username;
      const password = req.body?.password;

      if (
        typeof username !== 'string' ||
        validationUtils.validatePassword(password, /^/) === false
      ) {
        return next(
          ErrorCode.getCode(HTTP_STATUS.BAD_REQUEST, API_ERROR.USERNAME_PASSWORD_REQUIRED)
        );
      }

      auth.authenticate(username, password, async (err, user?: RemoteUser): Promise<void> => {
        if (err) {
          const errorCode = err.message ? HTTP_STATUS.UNAUTHORIZED : HTTP_STATUS.INTERNAL_ERROR;
          if (errorCode === HTTP_STATUS.UNAUTHORIZED) {
            res.set(HEADERS.WWW_AUTH, TOKEN_BEARER);
          }
          return next(ErrorCode.getCode(errorCode, err.message));
        } else {
          req.remote_user = user as RemoteUser;
          const jWTSignOptions: JWTSignOptions = getSecurity(config).web.sign;
          res.set(HEADERS.CACHE_CONTROL, 'no-cache, no-store');
          return next({
            token: await auth.jwtEncrypt(user as RemoteUser, jWTSignOptions),
            username: req.remote_user.name,
          });
        }
      });
    }
  );

  if (config?.flags?.changePassword === true) {
    route.put(
      wrapSecPath(WebUrls.reset_password),
      function (req: Request, res: Response, next: $NextFunctionVer): void {
        if (_.isNil(req.remote_user.name)) {
          res.status(HTTP_STATUS.UNAUTHORIZED);
          return next({
            // FUTURE: update to a more meaningful message
            message: API_ERROR.MUST_BE_LOGGED,
          });
        }

        const password = req.body?.password;
        const { name } = req.remote_user;

        // Existing passwords may predate the current password policy.
        if (
          validationUtils.validatePassword(password?.old, /^/) === false ||
          validationUtils.validatePassword(password?.new) === false
        ) {
          return next(ErrorCode.getCode(HTTP_STATUS.BAD_REQUEST, APP_ERROR.PASSWORD_VALIDATION));
        }

        auth.changePassword(name as string, password.old, password.new, (err, isUpdated): void => {
          if (_.isNil(err) && isUpdated) {
            next({
              ok: true,
            });
          } else if (!_.isNil(err)) {
            return next(
              ErrorCode.getCode(
                _.isNil(err.status) ? HTTP_STATUS.CONFLICT : err.status,
                err.message
              )
            );
          } else {
            return next(ErrorCode.getInternalError(API_ERROR.INTERNAL_SERVER_ERROR));
          }
        });
      }
    );
  }

  return route;
}

export default addUserAuthApi;
